sys_variable_value.value:
(function execute(inputs, outputs) {

    gs.info(inputs.marca);

    if(inputs.marca == 'Sim' || inputs.marca == 'Yes' || inputs.marca == true || inputs.marca == 'sim' || inputs.marca == 'yes'){
        outputs.resultmarca = 'alterar';
    } else {
        outputs.resultmarca = 'cadastrar';
    }

})(inputs, outputs);

